val Gold=Color(0xFFF4CD70);val Violet=Color(0xFFAD62FF);val Cyan=Color(0xFF4ADFFF);val Navy=Color(0xFF060918)
@Composable fun FavorTheme(content:@Composable ()->Unit){ MaterialTheme(colorScheme=darkColorScheme(primary=Gold,secondary=Violet,background=Navy,surface=Color(0xFF11172D),onSurface=Color(0xFFF5F2FF),error=Color(0xFFFF8192)),typography=Typography(),content=content) }
@Composable fun Backdrop(content:@Composable BoxScope.()->Unit){ Box(Modifier.fillMaxSize().background(Brush.linearGradient(listOf(Color(0xFF160C2B),Navy,Color(0xFF071826))))){ Canvas(Modifier.fillMaxSize()){ val w=size.width;val h=size.height;drawCircle(Brush.radialGradient(listOf(Violet.copy(alpha=.13f),Color.Transparent),center=Offset(w*.85f,h*.25f),radius=w*.9f),w*.9f,Offset(w*.85f,h*.25f));for(i in 0..4){val p=Path().apply{moveTo(-w*.1f,h*(.15f+i*.018f));cubicTo(w*.5f,h*.02f,w*.65f,h*.4f,w*1.1f,h*.1f)};drawPath(p,Violet.copy(alpha=.1f),style=Stroke(2f))} };content() } }
@Composable fun Brand(admin:Boolean=false,large:Boolean=false){ Column(horizontalAlignment=Alignment.CenterHorizontally,modifier=Modifier.fillMaxWidth().padding(vertical=16.dp)){Text("B5",fontSize=if(large)68.sp else 35.sp,fontWeight=FontWeight.Black,fontStyle=FontStyle.Italic,color=Gold,letterSpacing=(-3).sp);Text("S T U D I O S",fontSize=if(large)15.sp else 10.sp,color=Color(0xFFE8E7F2));if(large){Spacer(Modifier.height(16.dp));Text(if(admin)"PRIVATE ADMIN PANEL" else "USA FAVOR VPN",fontSize=22.sp,fontWeight=FontWeight.Bold,color=Gold)} } }
@Composable fun Shield(modifier:Modifier=Modifier){ Canvas(modifier.size(130.dp)){ val w=size.width;val h=size.height;val p=Path().apply{moveTo(w*.5f,h*.04f);lineTo(w*.88f,h*.22f);lineTo(w*.83f,h*.63f);quadraticBezierTo(w*.7f,h*.86f,w*.5f,h*.98f);quadraticBezierTo(w*.3f,h*.86f,w*.17f,h*.63f);lineTo(w*.12f,h*.22f);close()};drawPath(p,Brush.linearGradient(listOf(Violet,Color(0xFF151645),Cyan)));drawPath(p,Gold,style=Stroke(4f));val inner=Path().apply{moveTo(w*.5f,h*.17f);lineTo(w*.75f,h*.29f);lineTo(w*.72f,h*.58f);lineTo(w*.5f,h*.81f);lineTo(w*.28f,h*.58f);lineTo(w*.25f,h*.29f);close()};drawPath(inner,Color.White);for(i in 0..5)drawLine(Color(0xFFEA3D69),Offset(w*.3f,h*(.33f+i*.065f)),Offset(w*.71f,h*(.33f+i*.065f)),h*.027f);drawRect(Color(0xFF253B91),Offset(w*.28f,h*.28f),androidx.compose.ui.geometry.Size(w*.23f,h*.25f));for(x in 0..2)for(y in 0..3)drawCircle(Color.White,w*.009f,Offset(w*(.32f+x*.07f),h*(.32f+y*.05f))) } }
@Composable fun Skyline(){Canvas(Modifier.fillMaxWidth().height(100.dp)){val w=size.width;val h=size.height;for(i in 0..25){val x=i*w/26;val bh=h*(.2f+((i*17)%11)/15f);drawRect(Color(0xFF20203E),Offset(x,h-bh),androidx.compose.ui.geometry.Size(w/30,bh));for(y in 1..5)drawRect(Gold.copy(alpha=.35f),Offset(x+3,h-bh+y*9),androidx.compose.ui.geometry.Size(3f,3f))};drawLine(Violet,Offset(w*.78f,h*.05f),Offset(w*.78f,h),w*.025f);drawLine(Gold,Offset(w*.78f,0f),Offset(w*.78f,h*.18f),2f);drawLine(Cyan.copy(alpha=.4f),Offset(0f,h-2),Offset(w,h-2),2f)}}
@Composable fun Glass(title:String?=null,content:@Composable ColumnScope.()->Unit){ Column(Modifier.fillMaxWidth().padding(vertical=6.dp).clip(RoundedCornerShape(18.dp)).background(Brush.linearGradient(listOf(Color(0xCC20203B),Color(0xCC101828)))).border(1.dp,Brush.linearGradient(listOf(Violet.copy(alpha=.5f),Gold.copy(alpha=.18f))),RoundedCornerShape(18.dp)).padding(16.dp)){if(title!=null){Text(title,color=Gold,fontWeight=FontWeight.SemiBold);Spacer(Modifier.height(12.dp))};content()} }
@Composable fun Action(label:String,enabled:Boolean=true,onClick:()->Unit){Button(onClick,enabled=enabled,modifier=Modifier.fillMaxWidth().padding(vertical=5.dp).heightIn(min=50.dp),shape=RoundedCornerShape(12.dp),colors=ButtonDefaults.buttonColors(containerColor=Gold,contentColor=Navy)){Text(label,fontWeight=FontWeight.Bold)}}
@Composable fun Field(label:String,value:String,onValueChange:(String)->Unit,secret:Boolean=false){var visible by remember{mutableStateOf(false)};OutlinedTextField(value,onValueChange,label={Text(label)},modifier=Modifier.fillMaxWidth().padding(vertical=5.dp),shape=RoundedCornerShape(12.dp),singleLine=!label.contains("JSON"),visualTransformation=if(secret&&!visible)androidx.compose.ui.text.input.PasswordVisualTransformation() else androidx.compose.ui.text.input.VisualTransformation.None,trailingIcon=if(secret){{TextButton(onClick={visible=!visible}){Text(if(visible)"Hide" else "Show")}}}else null)}
@Composable fun Fact(name:String,value:String){ Row(Modifier.fillMaxWidth().padding(vertical=7.dp),horizontalArrangement=Arrangement.SpaceBetween){Text(name,color=Color(0xFFADB5CB),modifier=Modifier.weight(1f));Text(value,fontWeight=FontWeight.Medium,modifier=Modifier.weight(1f))} }
@Composable fun PageTitle(title:String,subtitle:String="POWERED BY B5 STUDIOS"){Column(Modifier.padding(vertical=12.dp)){Text(subtitle,color=Gold,fontSize=10.sp,letterSpacing=2.sp);Text(title,fontSize=27.sp,fontWeight=FontWeight.Bold)}}
@Composable fun PowerButton(state:String,onClick:()->Unit){val transition=rememberInfiniteTransition(label="power");val pulse by transition.animateFloat(.8f,1f,infiniteRepeatable(tween(1400),RepeatMode.Reverse),label="glow");Box(Modifier.padding(24.dp).size(190.dp).semanticsCompat(state).clickable(onClick=onClick),contentAlignment=Alignment.Center){Canvas(Modifier.fillMaxSize()){val c=if(state=="Connected")Color(0xFF51FF93)else Violet;drawCircle(Brush.radialGradient(listOf(c.copy(alpha=.3f*pulse),Color.Transparent)),size.minDimension/2);drawCircle(c.copy(alpha=.3f),size.minDimension*.37f,style=Stroke(18f*pulse));drawCircle(c,size.minDimension*.36f,style=Stroke(3f));drawArc(c, -45f,270f,false,topLeft=Offset(size.width*.36f,size.height*.35f),size=androidx.compose.ui.geometry.Size(size.width*.28f,size.height*.28f),style=Stroke(7f));drawLine(c,Offset(size.width*.5f,size.height*.3f),Offset(size.width*.5f,size.height*.48f),7f)}}}
fun Modifier.semanticsCompat(state:String)=this.semantics { contentDescription="VPN power: $state"; role=Role.Button }
